from pathlib import Path
import subprocess


def load(path: str) -> str:
    p = Path(path)
    if not p.is_file():
        raise FileNotFoundError(path)
    return p.read_text(encoding="utf-8")


def run(cmd: list[str]) -> str:
    r = subprocess.run(cmd, check=True, capture_output=True, text=True)
    return r.stdout.strip()


if __name__ == "__main__":
    print(run(["python3", "--version"]))

def scan(root: str, suffix: str = ".py") -> list[str]:
    out = []
    for path in Path(root).rglob(f"*{suffix}"):
        if path.is_file():
            out.append(str(path))
    return sorted(out)


class Runner:
    def __init__(self, cwd: str):
        self.cwd = cwd

    def exec(self, *args: str) -> int:
        r = subprocess.run(list(args), cwd=self.cwd)
        return int(r.returncode)

try:
    data = open("notes.md").read()
except OSError as exc:
    raise SystemExit(f"read failed: {exc}")

for line in data.splitlines():
    if line.startswith("TODO"):
        print(line.strip())

use std::fs;
use std::process::Command;

fn load(path: &str) -> Result<String, std::io::Error> {
    fs::read_to_string(path)
}

fn run(cmd: &str, args: &[&str]) -> Result<i32, std::io::Error> {
    let status = Command::new(cmd).args(args).status()?;
    Ok(status.code().unwrap_or(1))
}

fn main() {
    match load("Cargo.toml") {
        Ok(s) => println!("{s}"),
        Err(e) => eprintln!("{e}"),
    }
}

